package dev.admutium.techmod.client.suit;
import dev.admutium.techmod.suit.*;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;
public final class SuitInventoryScreen extends AbstractContainerScreen<SuitInventoryMenu>{
 public SuitInventoryScreen(SuitInventoryMenu menu,Inventory inv,Component title){super(menu,inv,title,186,menu.expanded?198:180);inventoryLabelX=12;inventoryLabelY=80;titleLabelX=12;titleLabelY=10;}
 @Override public void extractContents(GuiGraphicsExtractor g,int mx,int my,float dt){int x=leftPos,y=topPos;SuitUi.panel(g,x,y,186,menu.expanded?198:180);for(var slot:menu.slots)if(slot.isActive())SuitUi.slot(g,x+slot.x,y+slot.y);var compass=SuitClient.stationCompass();if(!compass.isEmpty()){g.item(minecraft.player,compass,x+12,y+28,0);g.text(font,SuitClient.homeText(),x+34,y+32,SuitUi.ACCENT);if(mx>=x+12&&mx<x+28&&my>=y+28&&my<y+44)g.setTooltipForNextFrame(font,java.util.List.of(Component.literal("Компас к станции экипировки")),java.util.Optional.empty(),mx,my);}if(menu.food){var d=SuitClient.wornData();int cap=32*d.level(SuitUpgrade.NUTRIENTS);g.text(font,"Еда",x+32,y+53,SuitUi.GREEN);g.text(font,d.contents().nutrients()+"/"+cap,x+32,y+64,SuitUi.MUTED);g.text(font,"Тара",x+114,y+53,SuitUi.TEXT);g.text(font,d.contents().emptyCans()+"/"+cap,x+114,y+64,SuitUi.MUTED);}super.extractContents(g,mx,my,dt);}
 @Override protected void extractLabels(GuiGraphicsExtractor g,int x,int y){g.text(font,title,12,10,SuitUi.TEXT);g.text(font,playerInventoryTitle,12,80,SuitUi.MUTED);}
}
